import React, { useEffect, useMemo, useState } from "react";
import { Box, Text, useInput } from "ink";
import { LOGO_CELLS, LOGO_COLS, LOGO_ROWS } from "../generated/logo.ts";
import { theme } from "../theme.ts";

/**
 * Terminal port of the embedme.html intro: every cell of the stroke-outline
 * logo carries a reveal time from the per-path staggered draw, then a light
 * sweep crosses the mark, then the wordmark cascades in with an orange
 * shimmer over GLINT. Any key skips.
 */

const DRAW_MS = 2300;
const SWEEP_START = DRAW_MS + 120;
const SWEEP_MS = 600;
const WORD = "GLINT RESEARCH";
const WORD_START = SWEEP_START + SWEEP_MS + 150;
const LETTER_STEP = 45;
const SHIMMER_START = WORD_START + WORD.length * LETTER_STEP + 300;
const SHIMMER_MS = 750;
const TOTAL = SHIMMER_START + SHIMMER_MS + 400;
const FPS_MS = 33;

export function Intro({ onDone }: { onDone: () => void }): React.ReactElement {
  const [t, setT] = useState(0);

  useInput(() => onDone());

  useEffect(() => {
    const started = Date.now();
    const timer = setInterval(() => {
      const elapsed = Date.now() - started;
      if (elapsed >= TOTAL) {
        clearInterval(timer);
        onDone();
        return;
      }
      setT(elapsed);
    }, FPS_MS);
    return () => clearInterval(timer);
  }, [onDone]);

  const settleFlash = t >= SWEEP_START + SWEEP_MS && t < SWEEP_START + SWEEP_MS + 220;

  const rows = useMemo(() => {
    const sweepActive = t >= SWEEP_START && t < SWEEP_START + SWEEP_MS;
    const sweepPos = sweepActive
      ? ((t - SWEEP_START) / SWEEP_MS) * (LOGO_COLS + LOGO_ROWS * 2 + 20) - 10
      : -1;
    const bits: number[][] = Array.from({ length: LOGO_ROWS }, () => new Array(LOGO_COLS).fill(0));
    const bright: boolean[][] = Array.from({ length: LOGO_ROWS }, () =>
      new Array(LOGO_COLS).fill(false),
    );
    for (const [row, col, cellBits, permille] of LOGO_CELLS) {
      if ((permille / 1000) * DRAW_MS > t) continue;
      bits[row][col] |= cellBits;
      if (sweepActive && Math.abs(col + row * 2 - sweepPos) < 6) bright[row][col] = true;
    }
    return bits.map((rowBits, r) => {
      const segs: Array<{ text: string; bright: boolean }> = [];
      let cur = "";
      let curBright = false;
      for (let c = 0; c < rowBits.length; c++) {
        const ch = rowBits[c] === 0 ? " " : String.fromCharCode(0x2800 + rowBits[c]);
        const b = bright[r][c];
        if (b !== curBright && cur) {
          segs.push({ text: cur, bright: curBright });
          cur = "";
        }
        curBright = b;
        cur += ch;
      }
      if (cur) segs.push({ text: cur, bright: curBright });
      return segs;
    });
  }, [t]);

  const letters: React.ReactNode[] = [];
  const shimmerT = (t - SHIMMER_START) / SHIMMER_MS;
  for (let i = 0; i < WORD.length; i++) {
    const visible = t >= WORD_START + i * LETTER_STEP;
    const isGlint = i < 5;
    let color = isGlint ? theme.orange : theme.ink;
    let bold = isGlint;
    if (visible && isGlint && shimmerT >= 0 && shimmerT <= 1) {
      const wave = shimmerT * 8 - i;
      if (wave > -1 && wave < 1.6) {
        color = theme.amber;
        bold = true;
      }
    }
    letters.push(
      <Text key={i} bold={bold} color={color}>
        {visible ? WORD[i] : " "}
      </Text>,
    );
  }
  const wordSpaced = letters.flatMap((l, i) => (i === 0 ? [l] : [<Text key={`s${i}`}> </Text>, l]));
  const pad = Math.max(0, Math.floor((LOGO_COLS - (WORD.length * 2 - 1)) / 2));

  return (
    <Box flexDirection="column" paddingLeft={2} paddingTop={1} paddingBottom={1}>
      {rows.map((segs, r) => (
        <Text key={r}>
          {segs.length === 0 ? (
            " "
          ) : (
            segs.map((s, i) => (
              <Text
                key={i}
                bold={s.bright || settleFlash}
                color={s.bright ? "#FFFFFF" : settleFlash ? theme.amber : theme.ink}
              >
                {s.text}
              </Text>
            ))
          )}
        </Text>
      ))}
      <Box marginTop={1} marginLeft={pad}>
        <Text>{wordSpaced}</Text>
      </Box>
      <Box marginLeft={pad}>
        <Text color={theme.faint} dimColor>
          {t > WORD_START ? " we teach tiny neural networks to think" : " "}
        </Text>
      </Box>
    </Box>
  );
}
